var webApp=function(dnaDom,fetchJson,prettyPrintJson){"use strict";const appConfig={apiServers:[{website:"localhost",api:"http://localhost:2121/api/v1"}]};const utils={isCurrentWebsite(server){return server.website===globalThis.location.hostname}};const appLookup={apiServer:appConfig.apiServers.find(utils.isCurrentWebsite)?.api};const appUi={logApiCall(method,url){const citeVerbElem=globalThis.document.querySelector("main >p >cite >code");const citeUrlElem=globalThis.document.querySelector("main >p >cite >output");citeVerbElem.textContent=method;citeUrlElem.textContent=url},handleBooks(data){const outputElem=globalThis.document.querySelector("main >pre >output");outputElem.innerHTML=prettyPrintJson.prettyPrintJson.toHtml(data);dna.ui.fadeIn(outputElem,{duration:1e3,reset:true});return outputElem}};const appAction={getBooks(){const url=`${appLookup.apiServer}/books`;appUi.logApiCall("GET",url);fetchJson.fetchJson.get(url).then(appUi.handleBooks)},getBook(button){const id=button.dataset.book;const url=`${appLookup.apiServer}/books/${id}`;appUi.logApiCall("GET",url);return fetchJson.fetchJson.get(url).then(appUi.handleBooks)},queryBooks(button){const ids=button.dataset.books.split(",").map(id=>Number(id));const query={ids:ids};const url=`${appLookup.apiServer}/books`;appUi.logApiCall("QUERY",url);fetchJson.fetchJson.query(url,query).then(appUi.handleBooks)},deleteBook(button){const id=button.dataset.book;const url=`${appLookup.apiServer}/books/${id}`;appUi.logApiCall("DELETE",url);fetchJson.fetchJson.delete(url).then(appUi.handleBooks)},bogus(){const url=`${appLookup.apiServer}/bogus`;appUi.logApiCall("GET",url);fetchJson.fetchJson.get(url).then(appUi.handleBooks)}};const webApp={action:appAction,setup(){fetchJson.fetchJson.enableLogger();console.info("simple-node-mvc-starter-project",appLookup.apiServer)}};dnaDom.dna.dom.onReady(webApp.setup);return webApp}(globalThis,globalThis,globalThis);
